// apps/langseth3d_bench.cpp — Langseth & LeVeque (2000) JCP 165, §3.3
// "Vorticity Generated by a Shock Wave" — the genuinely-3D two-perpendicular-
// cylinder problem (single-fluid Euler, shock-driven, large dt, short t_end).
//
//   Domain [0,1.5]x[0,1]x[0,0.5], symmetry (slip-wall) planes x=0,y=0,z=0,
//   transmissive outer faces. gamma=1.4, gas at rest, rho=p=1 EXCEPT:
//     - cylinder along z-axis  (axis x=y=0),   r=0.2: rho=1,   p=10  (drives shock)
//     - cylinder along y-axis  (axis x=0.4,z=0),r=0.2: rho=0.1, p=1   (low-density)
//   The cylindrical shock hits the low-density cylinder -> baroclinic vorticity ->
//   rolled-up vortices (the 3D recon discriminator: dissipative schemes smear them).
//   Paper shows t=0.1,0.3,0.5 (Fig 8). Reference grid 300x200x100, Method(2,2,2)+MC.
//
// Env: N3_N (Nz; Nx=3*Nz, Ny=2*Nz; default 20 -> 60x40x20 smoke),
//      N3_RECON ("bj" MUSCL default | "bvd" THINC-QQ-BVD; GAUSS via THINCQQ_GAUSS=1),
//      N3_T (t_end, default 0.5), N3_CFL (default 0.4), N3_DUMP (slice file).
//      MOOD_ON=1 to enable a-posteriori positivity (strong p=10 shock).
#include "cfd/mesh.hpp"
#include "cfd/euler3d.hpp"
#include "cfd/reconstruct3d.hpp"
#include "cfd/reconstruct3d_o2.hpp"
#include "cfd/solver_euler3d.hpp"
#include "cfd/io_vtk.hpp"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <vector>
#include <chrono>
#include <string>

using namespace cfd;

int main() {
    Euler3D eq; eq.gamma = 1.4;
    const int Nz = std::getenv("N3_N") ? std::atoi(std::getenv("N3_N")) : 20;
    const int Nx = 3 * Nz, Ny = 2 * Nz;            // keep ~cubic cells on [1.5,1,0.5]
    const double T = std::getenv("N3_T") ? std::atof(std::getenv("N3_T")) : 0.5;
    const double cfl = std::getenv("N3_CFL") ? std::atof(std::getenv("N3_CFL")) : 0.4;
    const char* rec = std::getenv("N3_RECON");
    const bool use_bvd = rec && std::strcmp(rec, "bvd") == 0;
    const int recon = use_bvd ? RECON3_BVD : RECON3_BJ_VERTEX;
    // Langseth = strong-shock(p=10,Mach~3)-into-low-density(rho=0.1). The Euler BVD now
    // defaults to the MLP-limited (vertex-26 bounded, ψ∈[0,1]) smooth candidate, which is
    // shock-stable; the legacy UNLIMITED o2-quad candidate (no slope limiter) over-sharpens
    // this interface to vacuum → set BVD_UNLIMITED=1 to reproduce that divergence.

    Mesh m = build_structured_3d(Nx, Ny, Nz, 1.5, 1.0, 0.5,
                                 /*px*/false, /*py*/false, /*pz*/false);
    const int N = m.n_cells();
    std::vector<double> U0((size_t)5 * N);
    for (int c = 0; c < N; ++c) {
        double x = m.cell_centers[(size_t)c*3+0], y = m.cell_centers[(size_t)c*3+1],
               z = m.cell_centers[(size_t)c*3+2];
        double rho = 1.0, p = 1.0;                 // ambient at rest
        if (std::sqrt(x*x + y*y) < 0.2)            rho = 1.0,  p = 10.0;  // z-axis cyl (shock)
        else if (std::sqrt((x-0.4)*(x-0.4) + z*z) < 0.2) rho = 0.1, p = 1.0;  // y-axis cyl (low-rho)
        double W[5] = {rho, 0.0, 0.0, 0.0, p}, Uc[5]; eq.prim_to_cons(W, Uc);
        for (int v = 0; v < 5; ++v) U0[(size_t)v*N + c] = Uc[v];
    }
    // BC tags (1-based): 1 x_min,2 x_max,3 y_min,4 y_max,5 z_min,6 z_max.
    // symmetry planes (x=0,y=0,z=0) = reflective slip wall (kind 1); outer = transmissive (0).
    std::vector<BC3D> bcs(7);
    bcs[1].kind = 1; bcs[3].kind = 1; bcs[5].kind = 1;       // symmetry
    bcs[2].kind = 0; bcs[4].kind = 0; bcs[6].kind = 0;       // transmissive

    ReconCtx3D ctx = build_recon_ctx_3d(m);
    ReconCtx3DO2 o2ctx; const ReconCtx3DO2* o2p = nullptr;
    if (use_bvd) { o2ctx = build_recon_ctx_3d_o2(m); o2p = &o2ctx; }

    // N3_FLUX: 0=LLF(Rusanov, most dissipative/robust), 1=HLLC, 2=RHLLC(default), 4=HLL.
    const int flux = std::getenv("N3_FLUX") ? std::atoi(std::getenv("N3_FLUX")) : (int)FLUX3_RHLLC;
    int steps = 0; double tend = 0.0;
    auto t0 = std::chrono::steady_clock::now();
    Solve3DResult R = solve_euler3d(m, eq, U0, T, /*integrator*/2, cfl, -1.0,
                                    100000000, recon, &ctx, flux, &bcs, o2p);
    auto t1 = std::chrono::steady_clock::now();
    double wall = std::chrono::duration<double>(t1 - t0).count();
    steps = R.n_steps; tend = R.t;

    // diagnostics: rho/p range, positivity, total enstrophy (||curl u||^2 * V),
    //   central differences on the structured grid (interior cells only).
    auto idx = [&](int i,int j,int k){ return (size_t)((k*Ny + j)*Nx + i); };
    auto vel = [&](size_t c, double& u, double& v, double& w){
        double r = R.U[(size_t)0*N + c]; u = R.U[(size_t)1*N+c]/r; v = R.U[(size_t)2*N+c]/r; w = R.U[(size_t)3*N+c]/r; };
    double rmin=1e300,rmax=-1e300,pmin=1e300; bool finite=true; double ens=0.0;
    double dx=1.5/Nx, dy=1.0/Ny, dz=0.5/Nz;
    for (int c = 0; c < N; ++c) {
        double r = R.U[(size_t)0*N+c]; if(!std::isfinite(r)) finite=false;
        double W[5], Uc[5]; for(int v=0;v<5;++v) Uc[v]=R.U[(size_t)v*N+c]; eq.cons_to_prim(Uc,W);
        if(r<rmin)rmin=r; if(r>rmax)rmax=r; if(W[4]<pmin)pmin=W[4];
    }
    for (int k=1;k<Nz-1;++k) for(int j=1;j<Ny-1;++j) for(int i=1;i<Nx-1;++i){
        double up,um,vp,vm,wp,wm,ub,vb,wb;
        vel(idx(i+1,j,k),up,vp,wp); vel(idx(i-1,j,k),um,vm,wm); double dvdx=(vp-vm)/(2*dx), dwdx=(wp-wm)/(2*dx);
        vel(idx(i,j+1,k),up,vp,wp); vel(idx(i,j-1,k),um,vm,wm); double dudy=(up-um)/(2*dy), dwdy=(wp-wm)/(2*dy);
        vel(idx(i,j,k+1),up,vp,wp); vel(idx(i,j,k-1),um,vm,wm); double dudz=(up-um)/(2*dz), dvdz=(vp-vm)/(2*dz);
        double ox=dwdy-dvdz, oy=dudz-dwdx, oz=dvdx-dudy;
        ens += (ox*ox+oy*oy+oz*oz) * (dx*dy*dz);
    }
    std::printf("Langseth3D recon=%s%s N=%dx%dx%d(%d) rho=[%.4f,%.4f] p_min=%.4f finite=%d "
                "enstrophy=%.4f steps=%d t=%.4f wall=%.1fs%s\n",
                use_bvd?"bvd":"bj", (use_bvd&&std::getenv("THINCQQ_GAUSS"))?"+GAUSS":"",
                Nx,Ny,Nz,N, rmin,rmax,pmin,(int)finite, ens, steps, tend, wall,
                (pmin<=0||!finite)?"  [DIVERGED/neg-p]":"");

    // ── paper field output: VTK (full 3D volume) + CSV (y=0 roll plane), all primitives + |vorticity| ──
    std::vector<double> frho(N),fu(N),fv(N),fw(N),fp(N),fvort(N,0.0);
    for(int c=0;c<N;++c){ double W[5],Uc[5]; for(int v=0;v<5;++v)Uc[v]=R.U[(size_t)v*N+c];
        eq.cons_to_prim(Uc,W); frho[c]=W[0];fu[c]=W[1];fv[c]=W[2];fw[c]=W[3];fp[c]=W[4]; }
    for(int k=1;k<Nz-1;++k)for(int j=1;j<Ny-1;++j)for(int i=1;i<Nx-1;++i){
        double up,um,vp,vm,wp,wm;
        vel(idx(i+1,j,k),up,vp,wp);vel(idx(i-1,j,k),um,vm,wm);double dvdx=(vp-vm)/(2*dx),dwdx=(wp-wm)/(2*dx);
        vel(idx(i,j+1,k),up,vp,wp);vel(idx(i,j-1,k),um,vm,wm);double dudy=(up-um)/(2*dy),dwdy=(wp-wm)/(2*dy);
        vel(idx(i,j,k+1),up,vp,wp);vel(idx(i,j,k-1),um,vm,wm);double dudz=(up-um)/(2*dz),dvdz=(vp-vm)/(2*dz);
        double ox=dwdy-dvdz,oy=dudz-dwdx,oz=dvdx-dudy; fvort[idx(i,j,k)]=std::sqrt(ox*ox+oy*oy+oz*oz);}
    std::vector<VtkField> flds={{"rho",frho.data()},{"u",fu.data()},{"v",fv.data()},{"w",fw.data()},{"p",fp.data()},{"vortmag",fvort.data()}};
    if(const char* vf=std::getenv("N3_VTK")){ write_vtk_image(vf,Nx,Ny,Nz,dx,dy,dz,flds); std::printf("VTK saved: %s\n",vf); }
    if(const char* cf=std::getenv("N3_CSV")){ FILE* fh=std::fopen(cf,"w"); if(fh){ int j=0;
        std::fprintf(fh,"x,z,rho,u,v,w,p,vortmag\n");
        for(int k=0;k<Nz;++k)for(int i=0;i<Nx;++i){ size_t c=idx(i,j,k);
            std::fprintf(fh,"%.6g,%.6g,%.7g,%.7g,%.7g,%.7g,%.7g,%.7g\n",
                m.cell_centers[c*3+0],m.cell_centers[c*3+2],frho[c],fu[c],fv[c],fw[c],fp[c],fvort[c]); }
        std::fclose(fh); std::printf("CSV saved: %s (y=0 slice %dx%d)\n",cf,Nx,Nz); } }
    // legacy text dump (back-compat): y=0 slice "x z rho"
    const char* df = std::getenv("N3_DUMP");
    if (df) { FILE* fh=std::fopen(df,"w"); if(fh){ int j=0;
        for(int k=0;k<Nz;++k) for(int i=0;i<Nx;++i){ size_t c=idx(i,j,k);
            std::fprintf(fh,"%.6g %.6g %.6g\n", m.cell_centers[c*3+0], m.cell_centers[c*3+2], R.U[(size_t)0*N+c]); }
        std::fclose(fh); } }
    return 0;
}
